cat > src/merge.js <<'EOF'
function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const sides = [mine, theirs]
  const items = [] // {kind, lines, base, mine, theirs}
  let pos = 0, k = 0
  const stable = to => {
    if (to > pos) items.push({ kind: 'stable', lines: base.slice(pos, to) })
  }
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    if (group.length === 1) {
      const c = group[0]
      items.push({ kind: c.who ? 'theirs' : 'mine', lines: sides[c.who].slice(c.ss, c.se) })
      continue
    }
    const baseL = base.slice(rs, re)
    const rep = [0, 1].map(w => {
      const g = group.filter(c => c.who === w)
      if (!g.length) return baseL
      const minB = Math.min(...g.map(c => c.bs)), maxB = Math.max(...g.map(c => c.be))
      const s = Math.min(...g.map(c => c.ss)) - (minB - rs)
      const e = Math.max(...g.map(c => c.se)) + (re - maxB)
      return sides[w].slice(s, e)
    })
    const [m, t] = rep
    if (eq(m, t)) items.push({ kind: 'both', lines: m })
    else if (eq(m, baseL)) items.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseL)) items.push({ kind: 'mine', lines: m })
    else items.push({ kind: 'conflict', mine: m, base: baseL, theirs: t })
  }
  stable(base.length)
  const out = []
  let conflict = false
  for (const it of items) {
    if (it.kind === 'conflict') conflict = true
    if (mode === 'regions') {
      out.push(it.kind === 'conflict'
        ? `conflict mine=${it.mine.length} base=${it.base.length} theirs=${it.theirs.length}`
        : `${it.kind} ${it.lines.length}`)
    } else if (it.kind === 'conflict') {
      out.push('<<<<<<< mine', ...it.mine)
      if (mode === 'merge') out.push('||||||| base', ...it.base)
      out.push('=======', ...it.theirs, '>>>>>>> theirs')
    } else out.push(...it.lines)
  }
  return { out, conflict }
}
