import { readFileSync } from 'node:fs'
import { parseFormula } from './parser.js'
import { Sheet } from './eval.js'
import { parseAddr, addrName } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  const a = parseAddr(raw)
  if (!a) fail(`line ${i + 1}: invalid cell address ${raw}`)
  const key = addrName(a)
  if (cells.has(key)) fail(`line ${i + 1}: cell ${key} is declared twice`)
  cells.set(key, { a, content })
}
function fail(msg) {
  process.stderr.write('error: ' + msg + '\n')
  process.exit(2)
}
const list = [...cells.values()].sort((x, y) => x.a.c - y.a.c || x.a.r - y.a.r)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const { a } of list) out.push(`${addrName(a)}=${sheet.format(sheet.get(addrName(a)))}`)
} else {
  for (const { a, content } of list) {
    let deps = []
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (ast) deps = collect(ast)
    }
    out.push(`${addrName(a)}:` + deps.map((d) => ' ' + d).join(''))
  }
}
function collect(ast) {
  const set = new Map()
  const walk = (n) => {
    if (!n) return
    switch (n.t) {
      case 'ref': { const a = parseAddr(n.name); if (a) set.set(addrName(a), a); break }
      case 'range': {
        const p = parseAddr(n.a), q = parseAddr(n.b)
        if (p && q) {
          for (let c = Math.min(p.c, q.c); c <= Math.max(p.c, q.c); c++)
            for (let r = Math.min(p.r, q.r); r <= Math.max(p.r, q.r); r++) set.set(addrName({ c, r }), { c, r })
        }
        break
      }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  return [...set.values()].sort((x, y) => x.c - y.c || x.r - y.r).map(addrName)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
