    const int = (field, v, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) throw fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = w[0]
    if (d === 'bucket' || d === 'window') {
      const isB = d === 'bucket'
      if (w.length !== (isB ? 5 : 4)) throw fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      if (lastTick !== null) throw fail('declarations must come before the first event')
      if (!NAME.test(w[1])) throw fail(`invalid policy name ${w[1]}`)
