const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdChar = (c) => isLetter(c) || isDigit(c) || c === '_'

export function scan(source) {
  const s = Array.from(source)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, reason) => ({ error: { line: l, col: c, reason } })

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      let depth = 0
      while (i < n) {
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth--; if (depth === 0) break }
        else adv()
      }
      if (depth > 0) return fail(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) return fail(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isLetter(c) || c === '_') {
      let t = ''
      while (i < n && isIdChar(s[i])) t += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(t) ? 'keyword' : 'ident', body: t })
      continue
    }
    if (isDigit(c)) {
      let t = ''
      let bad = false
      const run = (ok) => {
        let got = false
        while (i < n) {
          if (ok(s[i])) { t += adv(); got = true }
          else if (s[i] === '_' && got && ok(s[i + 1])) t += adv()
          else break
        }
        return got
      }
      const p = (s[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        t += adv(); t += adv()
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { t += adv(); run(isDigit) }
        if (s[i] === 'e' || s[i] === 'E') {
          const a = s[i + 1], b = s[i + 2]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(b))) {
            t += adv()
            if (!isDigit(s[i])) t += adv()
            run(isDigit)
          }
        }
      }
      if (isIdChar(s[i])) {
        bad = true
        while (i < n && isIdChar(s[i])) t += adv()
      }
      if (bad) return fail(sl, sc, `invalid number ${t}`)
      tokens.push({ line: sl, col: sc, kind: 'number', body: t })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) return fail(sl, sc, 'unterminated string')
        const ch = s[i]
        if (ch === '\n') return fail(line, col, 'newline in string')
        if (ch === '"') { adv(); break }
        if (ch !== '\\') { v += adv(); continue }
        const el = line, ec = col
        adv()
        if (i >= n) return fail(sl, sc, 'unterminated string')
        const e = s[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { adv(); v += simple[e]; continue }
        const bad = () => fail(el, ec, `invalid escape \\${e}`)
        if (e === 'x') {
          if (!(isHex(s[i + 1]) && isHex(s[i + 2]))) return bad()
          adv()
          v += String.fromCodePoint(parseInt(s[i] + s[i + 1], 16))
          adv(); adv()
          continue
        }
