      if (isIdChar(s[i])) {
        bad = true
        while (i < n && isIdChar(s[i])) t += adv()
      }
      if (bad) return fail(sl, sc, `invalid number ${t}`)
      tokens.push({ line: sl, col: sc, kind: 'number', body: t })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) return fail(sl, sc, 'unterminated string')
        const ch = s[i]
        if (ch === '\n') return fail(line, col, 'newline in string')
        if (ch === '"') { adv(); break }
        if (ch !== '\\') { v += adv(); continue }
        const el = line, ec = col
        adv()
        if (i >= n) return fail(sl, sc, 'unterminated string')
        const e = s[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { adv(); v += simple[e]; continue }
        const bad = () => fail(el, ec, `invalid escape \\${e}`)
        if (e === 'x') {
          if (!(isHex(s[i + 1]) && isHex(s[i + 2]))) return bad()
          adv()
          v += String.fromCodePoint(parseInt(s[i] + s[i + 1], 16))
          adv(); adv()
          continue
        }
        if (e === 'u') {
          if (s[i + 1] !== '{') return bad()
          let j = i + 2, h = ''
          while (isHex(s[j])) h += s[j++]
          if (!h || s[j] !== '}') return bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) return bad()
          while (i <= j) adv()
          v += String.fromCodePoint(cp)
          continue
        }
        return bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT2.includes(two)) {
      adv(); adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: c })
      continue
    }
    return fail(sl, sc, `unexpected character ${c}`)
  }
  return { tokens }
}
