      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else throw new Error('bad token')
  }
  return toks
}

const CMP = new Set(['=', '<>', '<', '<=', '>', '>='])

function parse(toks) {
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new Error('expected ' + v); p++ }

  function comparison() {
    let l = additive()
    while (toks[p] && toks[p].k === 'op' && CMP.has(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: power() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'neg', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) throw new Error('eof')
    if (t.k === 'num') { p++; return { type: 'num', v: t.v } }
    if (isOp('(')) {
      p++
      const e = comparison()
      expect(')')
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (!isOp(')')) {
          args.push(comparison())
          while (isOp(',')) { p++; args.push(comparison()) }
        }
        expect(')')
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word') throw new Error('bad range')
        p++
        return { type: 'range', a: t.v, b: t2.v }
      }
      const up = t.v.toUpperCase()
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', word: t.v }
    }
    throw new Error('unexpected')
  }

  const node = comparison()
  if (p !== toks.length) throw new Error('trailing')
  return node
}

/** True when a range sits anywhere but directly as a call argument. */
function misplaced(node, direct = false) {
  switch (node.type) {
    case 'range': return !direct
    case 'bin': return misplaced(node.l) || misplaced(node.r)
    case 'neg': return misplaced(node.x)
    case 'call': return node.args.some((a) => misplaced(a, true))
    default: return false
  }
}

export function parseFormula(body) {
  try {
    const node = parse(tokenize(body))
    return { ok: true, node, misplaced: misplaced(node) }
  } catch {
    return { ok: false }
  }
}

export function rangeCells(r) {
  const a = parseAddress(r.a)
  const b = parseAddress(r.b)
  if (!a || !b) return null
  const out = []
  const c0 = Math.min(a.col, b.col), c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row), r1 = Math.max(a.row, b.row)
  for (let c = c0; c <= c1; c++) for (let rw = r0; rw <= r1; rw++) out.push({ col: c, row: rw })
  return out
}

export function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const n = c - 27
  return String.fromCharCode(65 + Math.floor(n / 26)) + String.fromCharCode(65 + (n % 26))
}

export function collectDeps(node) {
  const set = new Map()
  const add = (col, row) => set.set(col * 1000 + row, { col, row })
  const walk = (n) => {
    switch (n.type) {
      case 'ref': { const a = parseAddress(n.word); if (a) add(a.col, a.row); break }
      case 'range': { const cs = rangeCells(n); if (cs) for (const c of cs) add(c.col, c.row); break }
      case 'bin': walk(n.l); walk(n.r); break
      case 'neg': walk(n.x); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(node)
  return [...set.values()]
    .sort((x, y) => x.col - y.col || x.row - y.row)
    .map((d) => colName(d.col) + d.row)
}
"}

{"file_path":"src/eval.js","content":"/** Cell evaluation and value formatting. */
import { parseAddress } from './sheet.js'
import { rangeCells, colName } from './formula.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (v) => ({ t: 'e', v })
const num = (v) => (Number.isFinite(v) ? { t: 'n', v } : err('#DIV/0!'))

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(content) {
  if (content === '') return { t: 'n', v: 0 }
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.has(content)) return err(content)
  return { t: 's', v: content }
}

const rank = { n: 0, s: 1, b: 2 }
function cmpCodePoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cmpCodePoints(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

/** Reads a value as a number; returns a number or an error value. */
function toNum(v) {
  if (v.t === 'n') return v.v
  if (v.t === 'b') return v.v ? 1 : 0
  return err('#VALUE!')
}

export function evaluateAll(cells) {
  const byName = new Map(cells.map((c) => [c.name, c]))
  const memo = new Map()
  const active = new Set()

  function cellValue(name) {
    if (memo.has(name)) return memo.get(name)
    const c = byName.get(name)
    if (!c) return { t: 'n', v: 0 }
    if (active.has(name)) return err('#CYCLE!')
    active.add(name)
    let v
    if (!c.ast) v = literal(c.content)
    else if (!c.ast.ok || c.ast.misplaced) v = err('#ERR!')
    else v = ev(c.ast.node)
    active.delete(name)
    memo.set(name, v)
    return v
  }

  function binary(op, l, r) {
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (CMP_OPS[op]) return { t: 'b', v: CMP_OPS[op](compare(l, r)) }
    const a = toNum(l)
    if (typeof a !== 'number') return a
    const b = toNum(r)
    if (typeof b !== 'number') return b
    switch (op) {
      case '+': return num(a + b)
      case '-': return num(a - b)
      case '*': return num(a * b)
      case '/': return b === 0 ? err('#DIV/0!') : num(a / b)
      default: return num(Math.pow(a, b))
    }
  }

  /** Values an argument contributes: array of values. */
  function argValues(a) {
    if (a.type === 'range') {
      const cs = rangeCells(a)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => cellValue(colName(c.col) + c.row))
    }
    return [ev(a)]
  }

  function call(n) {
    const { name, args } = n
    const isAgg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)
    if (!isAgg && name !== 'ABS' && name !== 'IF') return err('#NAME?')
    if (isAgg && args.length < 1) return err('#ERR!')
    if (name === 'ABS' && args.length !== 1) return err('#ERR!')
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const cond = ev(args[0])
      if (cond.t === 'e') return cond
      let truth
      if (cond.t === 'b') truth = cond.v
      else if (cond.t === 'n') truth = cond.v !== 0
      else return err('#VALUE!')
      return ev(args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      const v = ev(args[0])
      if (v.t === 'e') return v
      const x = toNum(v)
      return typeof x === 'number' ? num(Math.abs(x)) : x
    }
    const vals = args.flatMap(argValues)
    const firstErr = vals.find((v) => v.t === 'e')
    if (firstErr) return firstErr
    if (name === 'COUNT') return { t: 'n', v: vals.filter((v) => v.t === 'n').length }
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (typeof x !== 'number') return x
      nums.push(x)
    }
    switch (name) {
      case 'SUM': return num(nums.reduce((s, x) => s + x, 0))
      case 'AVG': return num(nums.reduce((s, x) => s + x, 0) / nums.length)
      case 'MIN': return num(Math.min(...nums))
      default: return num(Math.max(...nums))
    }
  }

  function ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': {
        const a = parseAddress(n.word)
        return a ? cellValue(a.name) : err('#REF!')
      }
      case 'range': return err('#VALUE!')
      case 'neg': {
        const v = ev(n.x)
        if (v.t === 'e') return v
        const x = toNum(v)
        if (typeof x !== 'number') return x
        return num(n.op === '-' ? -x : x)
      }
      case 'bin': {
        const l = ev(n.l)
        if (l.t === 'e') return l
        return binary(n.op, l, ev(n.r))
      }
      case 'call': return call(n)
    }
  }

  const out = new Map()
  for (const c of cells) out.set(c.name, cellValue(c.name))
  return out
}

const CMP_OPS = {
  '=': (d) => d === 0,
  '<>': (d) => d !== 0,
  '<': (d) => d < 0,
  '<=': (d) => d <= 0,
  '>': (d) => d > 0,
  '>=': (d) => d >= 0,
}
"}

