{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261006T225306Z/cell-Vwy9Ns/src/scanner.js","content":"const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isAlpha = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdent = (c) => isAlpha(c) || isDigit(c)

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4 + 1) * 4 + 1
    } else col++
    return c
  }

  // Consume a digit run with single underscores between digits.
  const run = (isD) => {
    let s = ''
    while (i < n) {
      if (isD(cs[i])) s += adv()
      else if (cs[i] === '_' && s !== '' && isD(cs[i - 1]) && isD(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line
      const sc = col
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      } while (depth > 0)
      continue
    }
    const sl = line
    const sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      adv()
      adv()
      let s = ''
      while (i < n && cs[i] !== '"') s += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      push('rawstring', JSON.stringify(s))
      continue
    }
    if (isAlpha(c)) {
      let s = ''
      while (i < n && isIdent(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let ok = true
      const p = cs[i + 1]
      const pre = c === '0' && p !== undefined ? { x: isHex, b: isBin, o: isOct }[p.toLowerCase()] : undefined
      if (pre) {
        s += adv()
        s += adv()
        const d = run(pre)
        if (d === '') ok = false
        s += d
      } else {
        s += run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) {
          s += adv()
          s += run(isDigit)
        }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(cs[i + 2]))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            s += run(isDigit)
          }
        }
      }
      if (i < n && isIdent(cs[i])) {
        ok = false
        while (i < n && isIdent(cs[i])) s += adv()
      }
      if (!ok) throw new ScanError(sl, sc, `invalid number ${s}`)
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch === '"') {
          adv()
          break
        }
        if (ch !== '\\') {
          v += adv()
          continue
        }
        const el = line
        const ec = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) v += simple[e]
        else if (e === 'x') {
          if (!(isHex(cs[i]) && isHex(cs[i + 1]))) throw bad()
          v += String.fromCharCode(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) throw bad()
          while (i <= j) adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else throw bad()
      }
      push('string', JSON.stringify(v))
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      adv()
      adv()
      push('punct', two)
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      push('punct', c)
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
"}

