{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261006T225306Z/cell-Z8Oc4R/src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) {
    super(msg)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const tasks = new Map()
  const deps = []
  const lines = text.split('\n')
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], { name: w[1], cost: BigInt(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const d of deps) {
    for (const name of d) if (!tasks.has(name)) throw new Fail(`error: unknown task ${name}`)
  }
  for (const [name, ...rest] of deps) for (const r of rest) tasks.get(name).deps.add(r)
  return tasks
}

function order(tasks) {
  const names = [...tasks.keys()].sort(cmp)
  const state = new Map()
  const stack = []
  const topo = []
  const visit = (name) => {
    state.set(name, 1)
    stack.push(name)
    for (const d of [...tasks.get(name).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        cyc.push(d)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(name, 2)
    topo.push(name)
  }
  for (const n of names) if (!state.get(n)) visit(n)
  return { names, topo }
}

function schedule(tasks, topo) {
  for (const name of topo) {
    const t = tasks.get(name)
    t.start = 0n
    t.depth = 0
    for (const d of t.deps) {
      const u = tasks.get(d)
      if (u.finish > t.start) t.start = u.finish
      if (u.depth + 1 > t.depth) t.depth = u.depth + 1
    }
    t.finish = t.start + t.cost
  }
}

function main() {
  const [cmd, ...rest] = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let workers = 0
  if (cmd === 'waves' || cmd === 'explain') {
    if (rest.length) throw new Fail(usage)
  } else if (cmd === 'pack') {
    if (rest.length !== 1) throw new Fail(usage)
    if (!/^[1-9][0-9]*$/.test(rest[0])) throw new Fail('error: workers must be a positive integer')
    workers = Number(rest[0])
  } else throw new Fail(usage)

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {}
  const tasks = parse(input)
  const { names, topo } = order(tasks)
  schedule(tasks, topo)
  let total = 0n
  for (const t of tasks.values()) if (t.finish > total) total = t.finish
  let out = ''

  if (cmd === 'waves') {
    const waves = []
    for (const n of names) (waves[tasks.get(n).depth] ??= []).push(n)
    waves.forEach((w, k) => {
      out += `wave ${k}: ${w.join(' ')}\n`
    })
    out += `total ${total}\n`
  } else if (cmd === 'explain') {
    for (const n of names) {
      const t = tasks.get(n)
      out += `${n} start=${t.start} finish=${t.finish} depth=${t.depth}\n`
    }
    out += `total ${total}\n`
  } else {
    const rdeps = new Map(names.map((n) => [n, []]))
    for (const t of tasks.values()) for (const d of t.deps) rdeps.get(d).push(t.name)
    for (const n of [...topo].reverse()) {
      const t = tasks.get(n)
      let best = 0n
      for (const r of rdeps.get(n)) if (tasks.get(r).prio > best) best = tasks.get(r).prio
      t.prio = t.cost + best
    }
    const freeAt = new Array(workers).fill(0n)
    const ran = Array.from({ length: workers }, () => [])
    const pending = new Set(names)
    let now = 0n
    let makespan = 0n
    while (pending.size) {
      for (;;) {
        let w = freeAt.findIndex((f) => f <= now)
        if (w < 0) break
        let pick = null
        for (const n of pending) {
          const t = tasks.get(n)
          let ready = true
          for (const d of t.deps) {
            const u = tasks.get(d)
            if (pending.has(d) || u.pfinish > now) {
              ready = false
              break
            }
          }
          if (!ready) continue
          if (!pick || t.prio > pick.prio || (t.prio === pick.prio && t.name < pick.name)) pick = t
        }
        if (!pick) break
        pending.delete(pick.name)
        pick.pfinish = now + pick.cost
        freeAt[w] = pick.pfinish
        ran[w].push(`${pick.name}@${now}-${pick.pfinish}`)
        if (pick.pfinish > makespan) makespan = pick.pfinish
      }
      if (!pending.size) break
      let next = null
      for (const f of freeAt) if (f > now && (next === null || f < next)) next = f
      if (next === null) break
      now = next
    }
    ran.forEach((r, i) => {
      out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`
    })
    out += `makespan ${makespan}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
"}

