const fail = (m) => { process.stderr.write(m + '\n'); process.exit(2) }
const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) fail('error: usage: cli.js rounds|tally')

const lines = require('node:fs').readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const nameRe = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line[0] === '#') return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (cands) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!nameRe.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (!cands) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (!cands) fail('error: no candidates')

