export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(n, m) }
    const count = (s, field, least) => {
      if (!COUNT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(s)
    }
    const decl = () => { if (events.length) fail('declarations must come before the first event') }
    switch (w[0]) {
      case 'bucket': {
        if (w.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        decl()
        if (!WORD.test(w[1])) fail(`invalid policy name ${w[1]}`)
        const capacity = count(w[2], 'capacity', 1)
        const refill = count(w[3], 'refill', 0)
        const per = count(w[4], 'per', 1)
        if (policies.has(w[1])) fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { kind: 'bucket', name: w[1], capacity, refill, per })
        break
      }
      case 'window': {
        if (w.length !== 4) fail('expected window <name> <limit> <span>')
        decl()
        if (!WORD.test(w[1])) fail(`invalid policy name ${w[1]}`)
        const limit = count(w[2], 'limit', 0)
        const span = count(w[3], 'span', 1)
        if (policies.has(w[1])) fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { kind: 'window', name: w[1], limit, span })
        break
      }
      case 'route': {
        if (w.length < 3) fail('expected route <prefix> <policy>...')
        decl()
        if (!WORD.test(w[1])) fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) fail(`prefix ${w[1]} is routed twice`)
        const list = w.slice(2).map((p) => {
          if (!policies.has(p)) fail(`unknown policy ${p}`)
          return policies.get(p)
        })
        routes.set(w[1], list)
        break
      }
      case 'event': {
        if (w.length !== 3) fail('expected event <tick> <key>')
        const tick = count(w[1], 'tick', 0)
        if (!WORD.test(w[2])) fail(`invalid key ${w[2]}`)
        if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: w[2] })
        break
      }
      default:
        fail(`unknown directive ${w[0]}`)
    }
  })
  return { routes, events }
}
