function makeState(p, tick) {
  if (p.kind === 'bucket') {
    // tokens are scaled by p.per so fractions stay exact
    return { last: tick, tokens: p.capacity * p.per }
  }
  return { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const n = tick - s.last
    s.last = tick
    if (n > 0n) {
      s.tokens += p.refill * n
      const cap = p.capacity * p.per
      if (s.tokens > cap) s.tokens = cap
    }
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}

const allows = (p, s) => (p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit)

function record(p, s, tick) {
  if (p.kind === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

export function run(model, mode) {
  const { routes, events } = model
  const states = new Map()
  const stats = new Map()
  let out = ''
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, list] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
    }
    let denier = null
    if (best) {
      const ss = best.list.map((p) => {
        const id = `${p.name}\n${key}`
        if (!states.has(id)) states.set(id, makeState(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < ss.length; i++) {
        if (!allows(best.list[i], ss[i])) { denier = best.list[i]; break }
      }
      if (!denier) best.list.forEach((p, i) => record(p, ss[i], tick))
    }
    const st = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, st)
    if (denier) { st.d++; td++ } else { st.a++; ta++ }
    if (mode === 'replay') out += denier ? `${tick} ${key} deny ${denier.name}\n` : `${tick} ${key} allow\n`
  }
  if (mode === 'summary') {
    for (const key of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out += `${key} allowed=${stats.get(key).a} denied=${stats.get(key).d}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
  return out
}
