      i++
      j++
      bs = i
      ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  flush(n, m)
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)

  const out = []
  let conflict = false
  const stable = (from, to) => {
    if (to <= from) return
    if (mode === 'regions') out.push(`stable ${to - from}`)
    else out.push(...base.slice(from, to))
  }
  const emit = (kind, ls) => {
    if (mode === 'regions') out.push(`${kind} ${ls.length}`)
    else out.push(...ls)
  }

  let pos = 0
  let k = 0
  while (k < all.length) {
    const first = all[k++]
    const group = [first]
    let end = first.be
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    const start = first.bs
    stable(pos, start)
    pos = end
    if (group.length === 1) {
      emit(first.who === 0 ? 'mine' : 'theirs', (first.who === 0 ? mine : theirs).slice(first.ss, first.se))
      continue
    }
    const side = who => {
      const cs = group.filter(c => c.who === who)
      const doc = who === 0 ? mine : theirs
      if (!cs.length) return base.slice(start, end)
      const minBs = Math.min(...cs.map(c => c.bs))
      const maxBe = Math.max(...cs.map(c => c.be))
      const s = Math.min(...cs.map(c => c.ss)) - (minBs - start)
      const e = Math.max(...cs.map(c => c.se)) + (end - maxBe)
      return doc.slice(s, e)
    }
    const m = side(0)
    const t = side(1)
    const b = base.slice(start, end)
    if (same(m, t)) emit('both', m)
    else if (same(m, b)) emit('theirs', t)
    else if (same(t, b)) emit('mine', m)
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${b.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...b)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    }
  }
  stable(pos, base.length)
  process.stdout.write(out.map(l => `${l}\n`).join(''))
  process.exitCode = conflict ? 1 : 0
}

